17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.server.ResponseStatusException;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        String normalizedAddress = normalizeAddress(owner.getAddress());
106	        if (normalizedAddress.isEmpty()) {
107	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
108	                "Address must not be blank after normalization");
109	        }
110	        owner.setAddress(normalizedAddress);
111	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
112	        owner.setTelephone(normalizedTelephone);
113	        owner.setEmail(normalizeEmail(owner.getEmail()));
114	        if (owner.getRegistrationDate() == null) {
115	            owner.setRegistrationDate(java.time.LocalDate.now());
116	        }
117	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
118	            .map(Owner::getTelephone)
119	            .filter(java.util.Objects::nonNull)
120	            .anyMatch(normalizedTelephone::equals);
121	        if (telephoneInUse) {
122	            throw new ResponseStatusException(HttpStatus.CONFLICT,
123	                "An owner with this telephone number already exists");
124	        }
125	        String lastNameKey = normalizeForHousehold(owner.getLastName());
126	        String addressKey = normalizeForHousehold(owner.getAddress());
127	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
128	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
129	                && normalizeForHousehold(existing.getAddress()).equals(addressKey))
130	            .toList();
131	        if (!householdMembers.isEmpty()) {
132	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
133	                throw new ResponseStatusException(HttpStatus.CONFLICT,
134	                    "An owner with this last name already exists at this address");
135	            }
136	            String householdId = householdId(lastNameKey, addressKey);
137	            owner.setHouseholdId(householdId);
138	            for (Owner member : householdMembers) {
139	                if (!householdId.equals(member.getHouseholdId())) {
140	                    member.setHouseholdId(householdId);
141	                    this.clinicService.saveOwner(member);
142	                }
143	            }
144	        }
145	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
146	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
147	        this.clinicService.saveOwner(owner);
148	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
149	        headers.setLocation(UriComponentsBuilder.newInstance()
150	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
151	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
152	    }
153	
154	    /**
155	     * Counts the owners that already exist (before the current create) whose first and last names
156	     * both match the supplied names, compared case-insensitively. The returned value is captured on
157	     * the new owner at creation time and does not change as further owners are added later.
158	     *
159	     * @param firstName the new owner's first name
160	     * @param lastName  the new owner's last name
161	     * @return the number of pre-existing namesake owners
162	     */
163	    private int namesakeCount(String firstName, String lastName) {
164	        return (int) this.clinicService.findAllOwners().stream()
165	            .filter(existing -> existing.getFirstName() != null
166	                && existing.getFirstName().equalsIgnoreCase(firstName)
167	                && existing.getLastName() != null
168	                && existing.getLastName().equalsIgnoreCase(lastName))
169	            .count();
170	    }
171	
172	    /**
173	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where
174	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} is the
175	     * upper-cased first three letters of the last name, and {@code NNNN} is a per-city 4-digit
176	     * zero-padded sequence equal to one more than the number of owners already in that city
177	     * (e.g. {@code 'SYD-SMI-0007'}).
178	     *
179	     * @param city     the owner's city
180	     * @param lastName the owner's last name
181	     * @return the assigned customer code
182	     */
183	    private String nextCustomerCode(String city, String lastName) {
184	        String cityPrefix = first3Upper(city);
185	        String lastPrefix = first3Upper(lastName);
186	        String cityKey = normalizeForHousehold(city);
187	        long sequence = this.clinicService.findAllOwners().stream()
188	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
189	            .count() + 1L;
190	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
191	    }
192	
193	    /**
194	     * Returns the upper-cased first three characters of {@code value}, or fewer if the value is
195	     * shorter. A {@code null} value yields the empty string.
196	     *
197	     * @param value the source value
198	     * @return the upper-cased first three characters
199	     */
200	    private String first3Upper(String value) {
201	        String v = (value == null ? "" : value);
202	        return v.substring(0, Math.min(3, v.length())).toUpperCase(java.util.Locale.ROOT);
203	    }
204	
205	    /**
206	     * Normalizes a street address applied whenever an owner is created: leading and trailing
207	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
208	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
209	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
210	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
211	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
212	     * {@code '12 MAIN STREET'}.
213	     *
214	     * @param address the raw address as submitted, or {@code null} when absent
215	     * @return the normalized address, or the empty string when the value is blank
216	     */
217	    private String normalizeAddress(String address) {
218	        String collapsed = (address == null ? "" : address)
219	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
220	        if (collapsed.isEmpty()) {
221	            return "";
222	        }
223	        String[] tokens = collapsed.split(" ");
224	        for (int i = 0; i < tokens.length; i++) {
225	            switch (tokens[i]) {
226	                case "ST" -> tokens[i] = "STREET";
227	                case "RD" -> tokens[i] = "ROAD";
228	                case "AVE" -> tokens[i] = "AVENUE";
229	                default -> { }
230	            }
231	        }
232	        return String.join(" ", tokens);
233	    }
234	
235	    /**
236	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
237	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
238	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
239	     * empty string.
240	     *
241	     * @param value the raw value (last name or address) as submitted
242	     * @return the normalized comparison key
243	     */
244	    private String normalizeForHousehold(String value) {
245	        if (value == null) {
246	            return "";
247	        }
248	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
249	    }
250	
251	    /**
252	     * Derives the stable shared household identifier for a household, keyed on the normalized last
253	     * name and address. Because it is a pure function of those normalized keys, every owner in the
254	     * same household deterministically computes the same value. The identifier is the first 12
255	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
256	     * (the separator prevents distinct name/address pairs from colliding).
257	     *
258	     * @param lastNameKey the normalized last-name comparison key
259	     * @param addressKey  the normalized address comparison key
260	     * @return the stable household identifier
261	     */
262	    private String householdId(String lastNameKey, String addressKey) {
263	        String seed = lastNameKey + "�" + addressKey;
264	        try {
265	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
266	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
267	            StringBuilder sb = new StringBuilder(digest.length * 2);
268	            for (byte b : digest) {
269	                sb.append(String.format("%02x", b));
270	            }
271	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
272	        }
273	        catch (java.security.NoSuchAlgorithmException e) {
274	            throw new IllegalStateException("SHA-256 not available", e);
275	        }
276	    }
277	
278	    /**
279	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
280	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
281	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
282	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
283	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
284	     * is stored as {@code '+61412345678'}.
285	     *
286	     * @param telephone the raw telephone number as submitted
287	     * @return the normalized E.164 telephone number
288	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
289	     *         number (8 to 15 digits after the '+')
290	     */
291	    private String normalizeTelephone(String telephone) {
292	        String raw = telephone == null ? "" : telephone.trim();
293	        String digits = raw.replaceAll("\\D", "");
294	        String e164;
295	        if (raw.startsWith("+")) {
296	            e164 = "+" + digits;
297	        } else {
298	            if (digits.startsWith("0")) {
299	                digits = digits.substring(1);
300	            }
301	            e164 = "+61" + digits;
302	        }
303	        int digitCount = e164.length() - 1;
304	        if (digitCount < 8 || digitCount > 15) {
305	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
306	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
307	        }
308	        return e164;
309	    }
310	
311	    /**
312	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
313	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
314	     * (absent) or already valid.
315	     *
316	     * @param email the email address as submitted, or {@code null} when absent
317	     * @return the lower-cased email, or {@code null} when absent
318	     */
319	    private String normalizeEmail(String email) {
320	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
321	    }
322	
323	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
324	    @Override
325	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
326	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
327	        if (currentOwner == null) {
328	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
329	        }
330	        currentOwner.setAddress(ownerFieldsDto.getAddress());
331	        currentOwner.setCity(ownerFieldsDto.getCity());
332	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
333	        currentOwner.setLastName(ownerFieldsDto.getLastName());
334	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
335	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
336	        this.clinicService.saveOwner(currentOwner);
337	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
338	    }
339	
340	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
341	    @Transactional
342	    @Override
343	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
344	        Owner owner = this.clinicService.findOwnerById(ownerId);
345	        if (owner == null) {
346	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
347	        }
348	        this.clinicService.deleteOwner(owner);
349	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
350	    }
351	
352	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
353	    @Override
354	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
355	        Owner owner = this.clinicService.findOwnerById(ownerId);
356	        if (owner == null) {
357	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
358	        }
359	        HttpHeaders headers = new HttpHeaders();
360	        Pet pet = petMapper.toPet(petFieldsDto);
361	        owner.setId(ownerId);
362	        pet.setOwner(owner);
363	        pet.getType().setName(null);
364	        this.clinicService.savePet(pet);
365	        PetDto petDto = petMapper.toPetDto(pet);
366	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
367	            .buildAndExpand(pet.getId()).toUri());
368	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
369	    }
370	
371	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
372	    @Override
373	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
374	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
375	        if (currentOwner != null) {
376	            Pet currentPet = this.clinicService.findPetById(petId);
377	            if (currentPet != null) {
378	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
379	                currentPet.setName(petFieldsDto.getName());
380	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
381	                this.clinicService.savePet(currentPet);
382	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
383	            }
384	        }
385	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
386	    }
387	
388	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
389	    @Override
390	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
391	        HttpHeaders headers = new HttpHeaders();
392	        Visit visit = visitMapper.toVisit(visitFieldsDto);
393	        Pet pet = new Pet();
394	        pet.setId(petId);
395	        visit.setPet(pet);
396	        this.clinicService.saveVisit(visit);
397	        VisitDto visitDto = visitMapper.toVisitDto(visit);
398	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
399	            .buildAndExpand(visit.getId()).toUri());
400	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
401	    }
402	
403	
404	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
405	    @Override
406	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
407	        Owner owner = this.clinicService.findOwnerById(ownerId);
408	        if (owner != null) {
409	            Pet pet = owner.getPet(petId);
410	            if (pet != null) {
411	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
412	            }
413	        }
414	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
415	    }
416	}
